INSERT INTO `posts` (`id`, `title`, `slug`, `content`, `author_id`, `category_id`, `created_at`, `updated_at`, `is_published`, `author`) VALUES
(1, 'Welcome to Mwalimu Link: Empowering Educators Nationwide', 'welcome-to-mwalimu-link-empowering-educators-nationwide', '<p data-start=\"163\" data-end=\"475\" class=\"\">We are excited to introduce <strong data-start=\"191\" data-end=\"207\">Mwalimu Link</strong>, a centralized platform dedicated to supporting teachers and schools across Kenya. From job opportunities and school applications to education resources and community engagement, Mwalimu Link is here to make a meaningful impact in the lives of educators and learners.</p><p data-start=\"477\" data-end=\"668\" class=\"\">Our mission is to bridge the gap between qualified teachers and schools in need, streamline school hiring processes, and offer a reliable source of information for all education stakeholders.</p><p data-start=\"670\" data-end=\"826\" class=\"\">Whether you\'re a teacher looking for your next opportunity or a school administrator searching for the right talent, Mwalimu Link is built with you in mind.</p><p data-start=\"828\" data-end=\"995\" class=\"\">🔹 <strong data-start=\"831\" data-end=\"867\">Find and apply for teaching jobs</strong><br data-start=\"867\" data-end=\"870\">
